/* =====================================================================
   FUEGO ASCII PARA UNA SECCIÓN  ·  fuego-seccion.js

   USO
   1. Guarda este archivo en tu proyecto (por ejemplo public/js/fuego-seccion.js).
   2. Cárgalo en la página, después del contenido:
        <script src="/js/fuego-seccion.js" data-selector="#obras"></script>
      data-selector = el contenedor (section/div) donde va el fuego de fondo.
      Si no pones data-selector usa  #obras.
   3. El fuego queda DETRÁS del contenido de esa sección (no toca el resto de la página),
      se pausa cuando la sección no está en pantalla y se adapta al tamaño del contenedor.

   Opcional en data-: data-opacidad="0.9"  (0 a 1, qué tan fuerte se ve el fuego)
   Aspecto: edita los valores del bloque CFG más abajo.
   ===================================================================== */
(function () {
  function arrancar() {
    (() => {
      // ---------- AJUSTES ----------
      // Todo lo que se quiera cambiar vive en DEF. CFG es la copia viva que modifica el panel.
      const NOMBRE = "FUEGO ASCII", ARCHIVO = "fuego-ascii.js";
      const FPS = 30;
      const RAMP = " .,:;-=+*#%@";       // de más vacío a más denso
      const FONDO = "#050109";           // color de fondo
      // ---- AJUSTES: edita estos valores para cambiar el aspecto ----
      const CFG = {
        ONDA: 1,                              // ondulación de las llamas
        VEL_ONDA: 1.3,                        // velocidad de las ondas
        PARPADEO: 1,                          // titileo de luz
        CHISPAS: 220,                         // cantidad de chispas
        VEL_CHISPAS: 1,                       // velocidad de las chispas
        VIENTO: 0.6,                          // empuje lateral de chispas
        COLOR_CHISPA: "#ffb23e",              // color de las chispas
        ZOOM: 1.08,                           // tamaño de la imagen
        DESP_Y: 0,                            // subir/bajar el encuadre
        BRILLO: 1,                            // brillo general
        SATURACION: 1.2,                      // 1 = color de la foto, mayor = más vivo
        GANANCIA: 1.25,                       // luz -> caracteres densos
        GAMMA: 0.95,                          // contraste
        UMBRAL: 0.05,                         // debajo de esto no se dibuja nada
        TINTE: "#ffffff",                     // tiñe toda la imagen
      };
      const DEF = CFG;
      const COM = {
        ONDA: "ondulación de las llamas", VEL_ONDA: "velocidad de las ondas", PARPADEO: "titileo de luz",
        CHISPAS: "cantidad de chispas", VEL_CHISPAS: "velocidad de las chispas", VIENTO: "empuje lateral de chispas",
        COLOR_CHISPA: "color de las chispas", ZOOM: "tamaño de la imagen", DESP_Y: "subir/bajar el encuadre",
        BRILLO: "brillo general", SATURACION: "1 = color de la foto, mayor = más vivo", GANANCIA: "luz -> caracteres densos",
        GAMMA: "contraste", UMBRAL: "debajo de esto no se dibuja nada", TINTE: "tiñe toda la imagen",
      };
      // la foto va incrustada en base64 (así funciona también abriendo el archivo desde el disco)
      const TEX = "data:image/jpeg;base64,";

      // filas del panel: [clave, etiqueta, mín, máx, paso, multiplicador para mostrar, unidad]
      const GRUPOS = [
        ["Llamas", [
          ["ONDA", "Ondulación", 0, 3, 0.05, 1, ""],
          ["VEL_ONDA", "Velocidad", 0.1, 4, 0.05, 1, ""],
          ["PARPADEO", "Parpadeo", 0, 3, 0.05, 1, ""],
        ]],
        ["Chispas", [
          ["CHISPAS", "Cantidad", 0, 500, 10, 1, ""],
          ["VEL_CHISPAS", "Velocidad", 0.2, 3, 0.05, 1, ""],
          ["VIENTO", "Viento", -3, 3, 0.1, 1, ""],
        ], { colores: [["Color", "COLOR_CHISPA"]] }],
        ["Imagen", [
          ["ZOOM", "Zoom", 1, 2, 0.05, 1, ""],
          ["DESP_Y", "Encuadre vertical", -0.15, 0.15, 0.01, 1, ""],
        ]],
        ["Look", [
          ["BRILLO", "Brillo", 0.5, 1.5, 0.05, 1, ""],
          ["SATURACION", "Saturación", 0, 2.5, 0.05, 1, ""],
          ["GANANCIA", "Luz", 0.8, 3.5, 0.05, 1, ""],
          ["GAMMA", "Contraste", 0.6, 2.2, 0.05, 1, ""],
        ], { colores: [["Tinte", "TINTE"]] }],
      ];

      // ---------- utilidades ----------
      const smooth = x => { x = x < 0 ? 0 : x > 1 ? 1 : x; return x * x * (3 - 2 * x); };
      const clamp = (x, a, b) => x < a ? a : x > b ? b : x;
      const hex = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
      const redondo = v => Math.round(v * 100) / 100;
      function seeded(seed) {
        return () => {
          seed |= 0; seed = seed + 0x6D2B79F5 | 0;
          let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
          t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
          return ((t ^ t >>> 14) >>> 0) / 4294967296;
        };
      }

      const tag = document.currentScript;
      const host = document.querySelector((tag && tag.dataset.selector) || "#obras");
      if (!host) { console.warn("fuego-seccion: no encontré el contenedor", tag && tag.dataset.selector); return; }
      const cv = document.createElement("canvas"), ctx = cv.getContext("2d");
      cv.setAttribute("aria-hidden", "true");
      if (getComputedStyle(host).position === "static") host.style.position = "relative";
      host.style.isolation = "isolate";                       // el canvas (z-index:-1) queda detrás del contenido pero encima del fondo de la sección
      host.style.overflow = "hidden";
      host.style.backgroundColor = FONDO;
      Object.assign(cv.style, {
        position: "absolute", top: "0", left: "0", width: "100%", height: "100%", zIndex: "-1", pointerEvents: "none", display: "block",
        opacity: (tag && tag.dataset.opacidad) || "1"
      });
      host.prepend(cv);
      let visible = true;
      if ("IntersectionObserver" in window) new IntersectionObserver(es => { visible = es[0].isIntersecting; }).observe(host);

      let W, H, dpr, CW, CH, cols, rows;
      let fase = 0;                          // fase ACUMULADA de las ondas (cambiar la velocidad en vivo no da saltos)
      let desv = 0;                          // corrimiento a la izquierda cuando el panel está abierto
      let tex = null, TW = 0, TH = 0;
      let fPet = [], P = [];
      const MAXP = 500;
      const px = [0, 0, 0];
      const still = matchMedia("(prefers-reduced-motion: reduce)");
      const recolor = () => { };              // (esta base no tiene paleta propia; el panel lo llama igual)
      const SUB = [[-0.25, -0.25], [0.25, -0.25], [-0.25, 0.25], [0.25, 0.25]];   // 4 sub-muestras por celda

      function resize() {
        dpr = Math.min(window.devicePixelRatio || 1, 2);
        W = host.clientWidth || 1; H = host.clientHeight || 1;
        CW = W < 700 ? 9 : 7; CH = Math.round(CW * 11 / 7);
        cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        cols = Math.ceil(W / CW); rows = Math.ceil(H / CH);
        const fam = 'Consolas, Menlo, "DejaVu Sans Mono", monospace';
        const fs = Math.round(CW * 12 / 7);
        ctx.font = `${fs}px ${fam}`;
        fPet = [1.0, 1.4, 1.9].map(k => `${Math.round(fs * k)}px ${fam}`);   // chispas lejanas, medias y cercanas
        const R = seeded(5);
        P = [];
        for (let i = 0; i < MAXP; i++) {
          const z = R();
          P.push({
            x0: 0.5 + (R() + R() + R() - 1.5) * 0.7, y0: 0.55 + R() * 0.55, dist: 0.45 + R() * 0.75,
            b: z < 0.45 ? 0 : z < 0.8 ? 1 : 2, rate: 0.14 + R() * 0.22, life: R(),
            amp: 0.01 + R() * 0.035, fr: 4 + R() * 8, ph: R() * 6.283, drift: 0.5 + R()
          });
        }
        ctx.textAlign = "center"; ctx.textBaseline = "middle";
      }

      // muestreo bilineal de la foto; (s,t) en 0..1 (se limita a los bordes). Deja r,g,b (0..1) en 'px'
      function sample(s, t) {
        s = s < 0 ? 0 : s > 0.9999 ? 0.9999 : s; t = t < 0 ? 0 : t > 0.9999 ? 0.9999 : t;
        const x = s * (TW - 1), y = t * (TH - 1);
        const x0 = x | 0, y0 = y | 0, fx = x - x0, fy = y - y0;
        const i00 = (y0 * TW + x0) * 4, i10 = i00 + 4, i01 = i00 + TW * 4, i11 = i01 + 4;
        const w00 = (1 - fx) * (1 - fy), w10 = fx * (1 - fy), w01 = (1 - fx) * fy, w11 = fx * fy;
        for (let k = 0; k < 3; k++)
          px[k] = (tex[i00 + k] * w00 + tex[i10 + k] * w10 + tex[i01 + k] * w01 + tex[i11 + k] * w11) / 255;
      }

      // las llamas ondulan más arriba que abajo
      const lengua = v => clamp(1.15 - v, 0.25, 1);

      // ---------- chispas: nacen abajo, suben zigzagueando y se enfrían ----------
      function mover(dt) {
        const n = Math.min(CFG.CHISPAS, MAXP);
        for (let i = 0; i < n; i++) {
          const p = P[i];
          p.life += dt * p.rate * CFG.VEL_CHISPAS;
          if (p.life >= 1) {                                // renace en otro lugar
            p.life -= 1; p.x0 = 0.5 + (Math.random() + Math.random() + Math.random() - 1.5) * 0.7;
            p.y0 = 0.55 + Math.random() * 0.55; p.ph = Math.random() * 6.283;
          }
        }
      }

      function chispas(intro, tt) {
        const n = Math.min(CFG.CHISPAS, MAXP);
        const pc = hex(CFG.COLOR_CHISPA);
        ctx.globalCompositeOperation = "lighter";            // se suman a la luz de la llama
        for (let b = 0; b < 3; b++) {
          ctx.font = fPet[b];
          for (let i = 0; i < n; i++) {
            const p = P[i];
            if (p.b !== b) continue;
            const L = p.life;
            const a = Math.pow(Math.sin(Math.PI * L), 0.7) * (0.75 + 0.25 * Math.sin(tt * 9 + p.ph * 5)) * intro;   // aparece, sube y se apaga
            if (a < 0.06) continue;
            const x = (p.x0 + CFG.VIENTO * 0.12 * L * p.drift + Math.sin(L * p.fr + p.ph) * p.amp * (0.4 + L)) * W - desv * H;
            const y = (p.y0 - L * p.dist) * H;
            // joven: amarillo-blanco; viejo: rojo oscuro
            const k = Math.max(0, 1 - L * 1.3);
            const r = pc[0] * (0.85 + 0.15 * k) + (255 - pc[0]) * k * 0.6, g = pc[1] * (1 - 0.65 * L) + (255 - pc[1]) * k * 0.5, bl = pc[2] * (1 - L) * 0.7 + 200 * k * k;
            ctx.fillStyle = `rgba(${r | 0},${g | 0},${bl | 0},${Math.min(1, a)})`;
            ctx.fillText(a > 0.75 ? "*" : a > 0.5 ? "+" : a > 0.3 ? "'" : ".", x, y);
          }
        }
        ctx.globalCompositeOperation = "source-over";
      }

      // ---------- dibujo: cada celda promedia 4 puntos de la foto (con las ondas) -> carácter + color ----------
      function draw(t) {
        ctx.fillStyle = FONDO;
        ctx.fillRect(0, 0, W, H);
        if (!tex) return;                                  // la foto todavía se está decodificando
        ctx.font = fPet.length ? `${Math.round(CW * 12 / 7)}px Consolas, Menlo, "DejaVu Sans Mono", monospace` : ctx.font;
        const { ZOOM, DESP_Y, ONDA, PARPADEO, BRILLO, SATURACION, GANANCIA, GAMMA, UMBRAL } = CFG;
        const tn = hex(CFG.TINTE).map(v => v / 255);
        const aspect = W / H, intro = 1, ar = TW / TH;   // sin intro: la escena se ve completa desde el primer cuadro
        // la foto cubre toda la pantalla (recorta arriba/abajo o a los lados, sin deformar)
        const ks = (aspect >= ar ? 1 / aspect : 1 / ar) / ZOOM, kt = (aspect >= ar ? ar / aspect : 1) / ZOOM;
        const dx = aspect / cols, dy = 1 / rows;
        const F = fase, parp = 1 + 0.05 * PARPADEO * (Math.sin(7.3 * F) + Math.sin(11.1 * F + 1)) / 2;   // titileo global

        for (let row = 0; row < rows; row++) {
          for (let c = 0; c < cols; c++) {
            let r = 0, g = 0, b = 0;
            for (let k = 0; k < 4; k++) {
              const X = ((c + 0.5) / cols - 0.5) * aspect + SUB[k][0] * dx + desv;
              const Y = (row + 0.5) / rows - 0.5 + SUB[k][1] * dy;
              let s = X * ks + 0.5, v = Y * kt + 0.5 + DESP_Y;
              // ondas que suben (+fase): tres ondas de distinto tamaño, más fuertes arriba
              const a = 0.020 * ONDA * lengua(v);
              const s2 = s - a * (0.55 * Math.sin(6.283 * (1.3 * v + 0.4 * s) + F) + 0.30 * Math.sin(6.283 * (2.7 * v - 0.9 * s) + 1.6 * F + 1.2) + 0.15 * Math.sin(6.283 * (5.1 * v + 1.3 * s) + 2.3 * F));
              v -= 0.45 * a * Math.sin(6.283 * (1.1 * s + 0.7 * v) + 1.4 * F + 2);
              s = s2;
              sample(s, v);
              r += px[0]; g += px[1]; b += px[2];
            }
            // luz que baila dentro de la llama
            const sc = ((c + 0.5) / cols - 0.5) * aspect * ks + 0.5, vc = ((row + 0.5) / rows - 0.5) * kt + 0.5 + DESP_Y;
            const bril = parp * (1 + 0.10 * PARPADEO * Math.sin(6.283 * (2 * sc + 3 * vc) + 3.1 * F));
            r *= 0.25 * tn[0] * bril; g *= 0.25 * tn[1] * bril; b *= 0.25 * tn[2] * bril;

            const lum = clamp(0.299 * r + 0.587 * g + 0.114 * b, 0, 1);
            const heat = Math.pow(clamp(lum * GANANCIA * intro, 0, 1), GAMMA);   // GANANCIA y GAMMA = el contraste
            if (heat <= UMBRAL) continue;
            const ch = RAMP[clamp(Math.floor(heat * (RAMP.length - 0.01)), 1, RAMP.length - 1)];
            // color de la foto normalizado por su canal máximo (vivo) y modulado por la luz
            const m = Math.max(r, g, b, 1e-4), mean = (r + g + b) / 3 / m;
            let nr = r / m, ng = g / m, nb = b / m;
            nr = mean + (nr - mean) * SATURACION; ng = mean + (ng - mean) * SATURACION; nb = mean + (nb - mean) * SATURACION;
            const l = (0.35 + 0.8 * heat) * BRILLO * 255;
            ctx.fillStyle = `rgb(${clamp(nr * l, 0, 255) | 0},${clamp(ng * l, 0, 255) | 0},${clamp(nb * l, 0, 255) | 0})`;
            ctx.fillText(ch, c * CW + CW / 2, row * CH + CH / 2);
          }
        }
        chispas(intro, F);
      }
      const dibujarQuieto = () => { fase = 0; draw(6); };

      const panel = { classList: { contains: () => true }, offsetWidth: 0 };   // (en el script exportado no hay panel)

      // ---------- bucle (arranca cuando la foto ya está decodificada) ----------
      const desvObjetivo = () => panel.classList.contains("cerrado") ? 0 : (panel.offsetWidth / 2) / H;
      resize();
      new ResizeObserver(() => { resize(); if (still.matches && tex) { desv = desvObjetivo(); dibujarQuieto(); } }).observe(host);

      let last = 0, t = 0;
      function loop(ms) {
        requestAnimationFrame(loop);
        if (still.matches || !visible || ms - last < 1000 / FPS) { if (!visible) last = 0; return; }
        const dt = last ? Math.min((ms - last) / 1000, 0.1) : 0;
        last = ms; t += dt;
        fase += dt * CFG.VEL_ONDA;
        mover(dt);
        desv += (desvObjetivo() - desv) * 0.15;
        draw(t);
      }

      const img = new Image();
      img.onload = () => {
        TW = img.width; TH = img.height;
        const oc = document.createElement("canvas"); oc.width = TW; oc.height = TH;
        const octx = oc.getContext("2d", { willReadFrequently: true });
        octx.drawImage(img, 0, 0);
        tex = octx.getImageData(0, 0, TW, TH).data;        // píxeles RGBA de la foto
        if (still.matches) { desv = desvObjetivo(); dibujarQuieto(); }
        requestAnimationFrame(loop);
      };
      img.src = TEX;
    })();
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar);
  else arrancar();
})();